class Merge(ContextCommand):
    """Merge commits"""

    def __init__(
        self, context: ApplicationContext, revision, no_commit, squash, no_ff, sign
    ) -> None:
        super().__init__(context)
        self.revision = revision
        self.no_ff = no_ff
        self.no_commit = no_commit
        self.squash = squash
        self.sign = sign

    def do(self) -> tuple[int, str, str]:
        squash = self.squash
        revision = self.revision
        no_ff = self.no_ff
        no_commit = self.no_commit
        sign = self.sign

        if prefs.verbose_simple_commands(self.context):
            merge_cmd = 'git merge '
            if sign:
                merge_cmd += '--gpg-sign '
            if no_ff:
                merge_cmd += '--no-ff '
            if no_commit:
                merge_cmd += '--no-commit '
            if squash:
                merge_cmd += '--squash '
            merge_cmd += revision
            self.context.notifier.git_cmd(merge_cmd)

        status, out, err = self.git.merge(
            revision, gpg_sign=sign, no_ff=no_ff, no_commit=no_commit, squash=squash
        )
        self.model.update_status()
        title = N_('Merge failed.  Conflict resolution is required.')
        self.context.notifier.command.emit(title, 'git merge', status, out, err)

        return status, out, err


